import { GoogleGenAI } from '@google/genai';

export const EMBEDDING_DIMENSION = 768;

/**
 * Deterministic semantic fallback vector generator for offline/local development.
 * Maps text keywords onto normalized 768-dimensional spherical coordinates.
 */
export function generateDeterministicEmbedding(text: string): number[] {
  const vec = new Array(EMBEDDING_DIMENSION).fill(0);
  const normalizedText = text.toLowerCase().trim();

  // Keyword semantic anchors
  const concepts: Record<string, number> = {
    water: 12,
    fountain: 13,
    shade: 45,
    tree: 46,
    bench: 78,
    quiet: 110,
    calm: 111,
    sun: 140,
    solar: 141,
    moss: 180,
    stone: 181,
    bird: 220,
    willow: 250,
    courtyard: 290,
    breeze: 330,
    garden: 380,
    zen: 410,
    flowers: 450,
    bamboo: 500,
    canopy: 550,
    rooftop: 600,
    peace: 650,
    stress: 700,
  };

  for (const [concept, baseIdx] of Object.entries(concepts)) {
    if (normalizedText.includes(concept)) {
      for (let offset = -4; offset <= 4; offset++) {
        const idx = (baseIdx + offset + EMBEDDING_DIMENSION) % EMBEDDING_DIMENSION;
        vec[idx] += 1.5 / (Math.abs(offset) + 1);
      }
    }
  }

  // Token hashing for vocabulary distribution
  for (let i = 0; i < normalizedText.length; i++) {
    const charCode = normalizedText.charCodeAt(i);
    const hash = (charCode * 31 + i * 17) % EMBEDDING_DIMENSION;
    vec[hash] += Math.sin(charCode + i) * 0.4;
  }

  // L2 normalize vector
  let norm = Math.hypot(...vec);
  if (norm === 0) norm = 1;
  return vec.map((v) => Number((v / norm).toFixed(6)));
}

/**
 * Generates 768-dimensional vector embedding for text using Google Gemini text-embedding-004.
 * Gracefully degrades to deterministic fallback if API key is not supplied.
 */
export async function getEmbedding(text: string): Promise<number[]> {
  const apiKey = process.env.GEMINI_API_KEY;

  if (apiKey && apiKey.trim() !== '') {
    try {
      const ai = new GoogleGenAI({ apiKey });
      const response = await ai.models.embedContent({
        model: 'text-embedding-004',
        contents: text,
      });

      if (response?.embedding?.values && response.embedding.values.length === EMBEDDING_DIMENSION) {
        return response.embedding.values;
      }
    } catch (error) {
      console.warn('Gemini embedding API call failed, using deterministic embedding fallback:', error);
    }
  }

  return generateDeterministicEmbedding(text);
}

/**
 * Calculates cosine similarity between two float vectors.
 */
export function cosineSimilarity(vecA: number[], vecB: number[]): number {
  if (vecA.length !== vecB.length) return 0;
  let dotProduct = 0;
  let normA = 0;
  let normB = 0;

  for (let i = 0; i < vecA.length; i++) {
    dotProduct += vecA[i] * vecB[i];
    normA += vecA[i] * vecA[i];
    normB += vecB[i] * vecB[i];
  }

  if (normA === 0 || normB === 0) return 0;
  return dotProduct / (Math.sqrt(normA) * Math.sqrt(normB));
}

/**
 * Formats vector as PostgreSQL pgvector string: '[0.123, -0.456, ...]'
 */
export function formatPgVector(vec: number[]): string {
  return `[${vec.join(',')}]`;
}

import { Pool, QueryResult } from 'pg';
import { INITIAL_SANCTUARIES, SanctuaryRecord } from './sanctuaries-data';
import { cosineSimilarity, formatPgVector } from '../lib/embeddings';

let pool: Pool | null = null;
let dbAvailable = false;

function getPool(): Pool | null {
  const connectionString = process.env.DATABASE_URL;
  if (!connectionString || connectionString.trim() === '' || connectionString.includes('your_tiger_data')) {
    return null;
  }

  if (!pool) {
    const isLocalhost = connectionString.includes('localhost') || connectionString.includes('127.0.0.1');
    pool = new Pool({
      connectionString,
      ssl: isLocalhost ? false : { rejectUnauthorized: false },
      connectionTimeoutMillis: 5000,
    });

    pool.on('error', (err) => {
      console.warn('Tiger Data PostgreSQL pool error (falling back to memory):', err.message);
      dbAvailable = false;
    });
  }

  return pool;
}

/**
 * Checks if Tiger Data PostgreSQL connection is active and responsive.
 */
export async function isDatabaseConnected(): Promise<boolean> {
  const p = getPool();
  if (!p) return false;

  try {
    const res = await p.query('SELECT 1');
    dbAvailable = res.rowCount !== null && res.rowCount > 0;
    return dbAvailable;
  } catch (err) {
    dbAvailable = false;
    return false;
  }
}

/**
 * Searches micro-sanctuaries using Tiger Data pgvector cosine distance `<=>`.
 * If database is not configured, performs in-memory cosine vector ranking.
 */
export async function querySanctuariesVector(
  embedding: number[],
  maxWalkMins: number = 20,
  limit: number = 3
): Promise<SanctuaryRecord[]> {
  const p = getPool();

  if (p) {
    try {
      const vectorLiteral = formatPgVector(embedding);
      const query = `
        SELECT 
          id, 
          name, 
          category, 
          neighborhood, 
          estimated_walk_mins, 
          shade_rating, 
          quiet_rating, 
          ambiance_description, 
          sensory_features, 
          (embedding <=> $1::vector) AS distance
        FROM micro_sanctuaries
        WHERE estimated_walk_mins <= $2
        ORDER BY distance ASC
        LIMIT $3;
      `;

      const result: QueryResult = await p.query(query, [vectorLiteral, maxWalkMins, limit]);
      if (result.rows.length > 0) {
        return result.rows.map((row) => ({
          id: row.id,
          name: row.name,
          category: row.category,
          neighborhood: row.neighborhood,
          estimated_walk_mins: row.estimated_walk_mins,
          shade_rating: row.shade_rating,
          quiet_rating: row.quiet_rating,
          ambiance_description: row.ambiance_description,
          sensory_features: row.sensory_features,
          distance: parseFloat(row.distance),
        }));
      }
    } catch (dbError) {
      console.warn('Tiger Data pgvector query failed, using in-memory vector fallback:', dbError);
    }
  }

  // Graceful In-Memory Semantic Cosine Ranking Fallback
  const candidateList = INITIAL_SANCTUARIES.filter(
    (s) => s.estimated_walk_mins <= maxWalkMins
  );

  const scored = candidateList.map((sanctuary) => {
    const sim = sanctuary.embedding ? cosineSimilarity(embedding, sanctuary.embedding) : 0.5;
    const distance = 1 - sim; // Cosine distance = 1 - cosine similarity
    return {
      ...sanctuary,
      distance: Number(distance.toFixed(4)),
    };
  });

  scored.sort((a, b) => (a.distance ?? 1) - (b.distance ?? 1));
  return scored.slice(0, limit);
}

/**
 * Records an outdoor disconnect session into Tiger Data
 */
export async function logDisconnectSession(
  sanctuaryId: number,
  targetDurationMins: number,
  reflectionNotes?: string
): Promise<number | null> {
  const p = getPool();
  if (!p) return null;

  try {
    const res = await p.query(
      `INSERT INTO disconnect_sessions (sanctuary_id, target_duration_mins, completed, reflection_notes)
       VALUES ($1, $2, TRUE, $3) RETURNING id`,
      [sanctuaryId, targetDurationMins, reflectionNotes || 'Touch grass completed']
    );
    return res.rows[0]?.id ?? null;
  } catch (error) {
    console.warn('Could not record disconnect session to database:', error);
    return null;
  }
}

export { getPool };

import dotenv from 'dotenv';
dotenv.config({ path: '.env.local' });
dotenv.config();

import { Pool } from 'pg';
import fs from 'fs';
import path from 'path';
import { INITIAL_SANCTUARIES } from './sanctuaries-data';
import { getEmbedding, formatPgVector } from '../lib/embeddings';

async function runSeed() {
  const dbUrl = process.env.DATABASE_URL;

  console.log('🌿 ==========================================');
  console.log('🌿 GroundTrace: Tiger Data pgvector Seeder');
  console.log('🌿 ==========================================\n');

  if (!dbUrl || dbUrl.trim() === '' || dbUrl.includes('your_tiger_data')) {
    console.log('ℹ️  No DATABASE_URL configured in .env or .env.local.');
    console.log('ℹ️  Tiger Data connection is required to seed PostgreSQL.');
    console.log('💡 Sign up for a free PostgreSQL database at Tiger Data / Timescale:');
    console.log('   https://console.tigerdata.io/ (or use any Postgres with pgvector).');
    console.log('ℹ️  Note: GroundTrace includes an in-memory vector fallback, so the web UI and agent');
    console.log('   run out of the box even before configuring DATABASE_URL!\n');
    return;
  }

  const isLocal = dbUrl.includes('localhost') || dbUrl.includes('127.0.0.1');
  const pool = new Pool({
    connectionString: dbUrl,
    ssl: isLocal ? false : { rejectUnauthorized: false },
    connectionTimeoutMillis: 10000,
  });

  try {
    console.log('Connecting to Tiger Data PostgreSQL...');
    const client = await pool.connect();
    console.log(' Connected successfully!\n');

    // 1. Read and apply schema
    const schemaPath = path.join(__dirname, 'schema.sql');
    const schemaSql = fs.readFileSync(schemaPath, 'utf8');

    console.log('⚙️  Applying pgvector schema & ivfflat index...');
    await client.query(schemaSql);
    console.log(' Schema applied successfully.\n');

    // 2. Clear previous entries if requested
    console.log(' Clearing existing test sanctuaries...');
    await client.query('DELETE FROM disconnect_sessions;');
    await client.query('DELETE FROM micro_sanctuaries;');

    // 3. Insert curated micro-sanctuaries with embeddings
    console.log(`🌱 Seeding ${INITIAL_SANCTUARIES.length} micro-sanctuaries with 768-dim embeddings...`);

    for (const sanctuary of INITIAL_SANCTUARIES) {
      const fullText = `${sanctuary.name}. Category: ${sanctuary.category}. Located in ${sanctuary.neighborhood}. ${sanctuary.ambiance_description} Sensory cues: ${sanctuary.sensory_features.join(', ')}`;

      // Get embedding from Gemini text-embedding-004 (or deterministic fallback)
      const embedding = await getEmbedding(fullText);
      const vectorLiteral = formatPgVector(embedding);

      const insertSql = `
        INSERT INTO micro_sanctuaries (
          name, category, neighborhood, estimated_walk_mins,
          shade_rating, quiet_rating, ambiance_description,
          sensory_features, embedding
        ) VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::vector)
        RETURNING id, name;
      `;

      const res = await client.query(insertSql, [
        sanctuary.name,
        sanctuary.category,
        sanctuary.neighborhood,
        sanctuary.estimated_walk_mins,
        sanctuary.shade_rating,
        sanctuary.quiet_rating,
        sanctuary.ambiance_description,
        sanctuary.sensory_features,
        vectorLiteral,
      ]);

      console.log(`   [#${res.rows[0].id}] ${res.rows[0].name} (${sanctuary.estimated_walk_mins}m walk) seeded.`);
    }

    // 4. Verify with a sample cosine vector similarity query
    console.log('\n🔎 Verifying vector cosine search (<=> operator)...');
    const testQuery = 'quiet shaded bench under ancient tree with water sound';
    const testVec = await getEmbedding(testQuery);
    const testRes = await client.query(
      `SELECT name, neighborhood, estimated_walk_mins, (embedding <=> $1::vector) AS distance
       FROM micro_sanctuaries
       ORDER BY distance ASC
       LIMIT 2;`,
      [formatPgVector(testVec)]
    );

    console.log(`Top matches for "${testQuery}":`);
    for (const row of testRes.rows) {
      console.log(`   ✨ ${row.name} (${row.neighborhood}) - Distance: ${Number(row.distance).toFixed(4)}`);
    }

    client.release();
    await pool.end();

    console.log('\n🎉 Tiger Data pgvector seeding complete! Ready for Hacktoberfest challenge.');
  } catch (error: any) {
    console.error('❌ Seeding failed:', error.message);
    await pool.end();
    process.exit(1);
  }
}

runSeed();

import { createTool } from '@mastra/core/tools';
import { z } from 'zod';
import { getEmbedding } from '../../lib/embeddings';
import { querySanctuariesVector } from '../../db/client';

export const searchSanctuariesInputSchema = z.object({
  userRequest: z
    .string()
    .describe('The user mental state, mood, or sensory requirement (e.g. "high screen fatigue, need deep shade and water")'),
  maxWalkMins: z
    .number()
    .default(15)
    .describe('Maximum walking time in minutes one-way (e.g. 5, 10, 15, 20)'),
  needQuiet: z
    .boolean()
    .default(true)
    .describe('Whether quiet solitude (minimal urban decibels) is requested'),
});

export const searchSanctuariesTool = createTool({
  id: 'searchSanctuariesTool',
  description:
    'Searches Tiger Data PostgreSQL using pgvector cosine distance (<=>) for nearby micro-sanctuaries matching user mood, sensory desires, and walk time.',
  inputSchema: searchSanctuariesInputSchema,
  execute: async ({ context }) => {
    const { userRequest, maxWalkMins, needQuiet } = context;

    // 1. Generate 768-dim query embedding using Gemini text-embedding-004
    const embedding = await getEmbedding(userRequest);

    // 2. Query Tiger Data PostgreSQL with pgvector <=> cosine distance
    const results = await querySanctuariesVector(embedding, maxWalkMins, 3);

    // 3. Apply quiet filter preference if available
    let filtered = results;
    if (needQuiet) {
      const quietCandidates = results.filter((s) => s.quiet_rating >= 4);
      if (quietCandidates.length > 0) {
        filtered = quietCandidates;
      }
    }

    return {
      totalFound: filtered.length,
      primarySanctuary: filtered[0] || null,
      alternatives: filtered.slice(1),
    };
  },
});

import { createTool } from '@mastra/core/tools';
import { z } from 'zod';

export const sensoryMissionInputSchema = z.object({
  sanctuaryName: z.string().describe('Name of the discovered micro-sanctuary'),
  category: z.string().describe('Category (e.g., pocket_park, quiet_bench, botanical_corner, urban_grove)'),
  sensoryFeatures: z.array(z.string()).describe('Sensory elements present at the location (e.g., moss, running water, shade)'),
  mood: z.string().describe('Current user mental state (e.g., screen fatigue, high stress, need sunlight)'),
  availableMins: z.number().default(20).describe('Total time window user has available'),
});

export const generateSensoryMissionTool = createTool({
  id: 'generateSensoryMissionTool',
  description:
    'Generates a restorative, screen-free sensory mindfulness mission tailored to the recommended micro-sanctuary and user stress level.',
  inputSchema: sensoryMissionInputSchema,
  execute: async ({ context }) => {
    const { sanctuaryName, category, sensoryFeatures, mood, availableMins } = context;

    // Craft rich grounded instructions based on location features
