  const totalSeconds = initialMinutes * 60;
  const [secondsRemaining, setSecondsRemaining] = useState<number>(totalSeconds);
  const [isRunning, setIsRunning] = useState<boolean>(true);
  const [promptIndex, setPromptIndex] = useState<number>(0);
  const [isUltraDimmed, setIsUltraDimmed] = useState<boolean>(false);
  const [isFinished, setIsFinished] = useState<boolean>(false);
  const [reflectionNotes, setReflectionNotes] = useState<string>('');
  const [hasLoggedSession, setHasLoggedSession] = useState<boolean>(false);

  // Reset state when opened
  useEffect(() => {
    if (isOpen) {
      setSecondsRemaining(initialMinutes * 60);
      setIsRunning(true);
      setIsFinished(false);
      setIsUltraDimmed(false);
      setHasLoggedSession(false);
      // Play initial meditative gong
      chime.playZenChime('start');
    }
  }, [isOpen, initialMinutes]);

  // Main countdown interval
  useEffect(() => {
    if (!isOpen || !isRunning || isFinished) return;

    const timer = setInterval(() => {
      setSecondsRemaining((prev) => {
        if (prev <= 1) {
          clearInterval(timer);
          setIsRunning(false);
          setIsFinished(true);
          chime.playZenChime('complete');
          return 0;
        }

        // Halfway gong reminder
        if (prev === Math.floor(totalSeconds / 2)) {
          chime.playZenChime('tick');
        }

        return prev - 1;
      });
    }, 1000);

    return () => clearInterval(timer);
  }, [isOpen, isRunning, isFinished, totalSeconds]);

  // Prompt rotator interval
  useEffect(() => {
    if (!isOpen) return;
    const promptTimer = setInterval(() => {
      setPromptIndex((prev) => (prev + 1) % MINDFUL_PROMPTS.length);
    }, 12000);

    return () => clearInterval(promptTimer);
  }, [isOpen]);

  // Handle ESC key
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        onClose();
      }
    };
    if (isOpen) {
      window.addEventListener('keydown', handleKeyDown);
    }
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  const minutes = Math.floor(secondsRemaining / 60);
  const seconds = secondsRemaining % 60;
  const progressPercent = ((totalSeconds - secondsRemaining) / totalSeconds) * 100;

  const handleFinishAndSave = async () => {
    if (!hasLoggedSession) {
      try {
        await fetch('/api/agent', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            action: 'complete_session',
            sanctuaryId,
            minutes: initialMinutes,
            notes: reflectionNotes || 'Touch grass walk completed',
          }),
        });
        setHasLoggedSession(true);
      } catch (err) {
        console.warn('Could not record session to database:', err);
      }
    }
    onClose();
  };

  return (
    <div
      className={`fixed inset-0 z-50 transition-opacity duration-700 flex flex-col items-center justify-between p-6 select-none ${
        isUltraDimmed
          ? 'bg-black text-stone-600'
          : 'bg-[#060c0a] text-emerald-100'
      }`}
    >
      {/* Ambient Breathing Glow */}
      {!isUltraDimmed && (
        <div className="absolute inset-0 overflow-hidden pointer-events-none">
          <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 w-[550px] h-[550px] bg-emerald-950/25 rounded-full blur-[140px] animate-breathe" />
        </div>
      )}

      {/* Top Bar */}
      <div className="w-full max-w-2xl flex items-center justify-between relative z-10">
        <div className="flex items-center gap-2">
          <TreePine className="w-4 h-4 text-emerald-400" />
          <span className="text-xs font-mono text-emerald-400/80 uppercase tracking-widest font-medium">
            Disconnect Lockout &bull; {sanctuaryName}
          </span>
        </div>

        <div className="flex items-center gap-3">
          {/* Dim screen toggle */}
          <button
            onClick={() => setIsUltraDimmed(!isUltraDimmed)}
            className="p-2 rounded-lg bg-emerald-950/40 hover:bg-emerald-900/40 text-emerald-300/80 transition-colors"
            title={isUltraDimmed ? 'Restore Brightness' : 'Ultra Dim Screen'}
          >
            {isUltraDimmed ? (
              <Eye className="w-4 h-4 text-emerald-400" />
            ) : (
              <EyeOff className="w-4 h-4" />
            )}
          </button>

          {/* Sound toggle */}
          <button
            onClick={onToggleSound}
            className="p-2 rounded-lg bg-emerald-950/40 hover:bg-emerald-900/40 text-emerald-300/80 transition-colors"
            title={soundEnabled ? 'Mute Chimes' : 'Enable Chimes'}
          >
            {soundEnabled ? (
              <Volume2 className="w-4 h-4 text-emerald-400" />
            ) : (
              <VolumeX className="w-4 h-4 text-emerald-700" />
            )}
          </button>

          {/* Close/Exit */}
          <button
            onClick={onClose}
            className="p-2 rounded-lg bg-emerald-950/40 hover:bg-emerald-900/40 text-emerald-300/80 hover:text-emerald-100 transition-colors"
            title="Exit Disconnect Mode"
          >
            <X className="w-4 h-4" />
          </button>
        </div>
      </div>

      {/* Center Countdown Display */}
      <div className="flex flex-col items-center justify-center my-auto text-center relative z-10 max-w-md w-full">
        {!isFinished ? (
          <>
            {/* Circular Timer Ring */}
            <div className="relative w-64 h-64 sm:w-72 sm:h-72 flex items-center justify-center mb-8">
              <svg className="w-full h-full -rotate-90" viewBox="0 0 100 100">
                {/* Background Ring */}
                <circle
                  cx="50"
                  cy="50"
                  r="44"
                  className="stroke-emerald-950/80"
                  strokeWidth="3.5"
                  fill="none"
                />
                {/* Animated Progress Ring */}
                <circle
                  cx="50"
                  cy="50"
                  r="44"
                  className="stroke-emerald-400 transition-all duration-1000 ease-linear"
                  strokeWidth="3.5"
                  strokeDasharray={276.46}
                  strokeDashoffset={276.46 - (276.46 * progressPercent) / 100}
                  strokeLinecap="round"
                  fill="none"
                />
              </svg>

              {/* Digits in Center */}
              <div className="absolute inset-0 flex flex-col items-center justify-center">
                <span className="font-mono text-5xl sm:text-6xl font-light text-emerald-50 tracking-tighter">
                  {String(minutes).padStart(2, '0')}:{String(seconds).padStart(2, '0')}
                </span>
                <span className="text-[11px] font-mono text-emerald-400/60 uppercase tracking-widest mt-1">
                  Offline Sanctuary Time
                </span>
              </div>
            </div>

            {/* Mindful Prompt Carousel */}
            <div className="min-h-[64px] flex items-center justify-center px-4">
              <p className="text-sm sm:text-base font-serif italic text-emerald-200/90 leading-relaxed transition-all duration-500">
                &ldquo;{MINDFUL_PROMPTS[promptIndex]}&rdquo;
              </p>
            </div>

            {/* Sub-label */}
            <p className="text-xs text-emerald-400/50 font-mono mt-3">
              Mission: {sensoryMissionTitle}
            </p>

            {/* Play/Pause & Reset Controls */}
            <div className="flex items-center gap-4 mt-8">
              <button
                onClick={() => setIsRunning(!isRunning)}
                className="p-3.5 rounded-full bg-emerald-900/40 hover:bg-emerald-800/50 border border-emerald-700/50 text-emerald-100 transition-all active:scale-95"
                title={isRunning ? 'Pause' : 'Resume'}
              >
                {isRunning ? (
                  <Pause className="w-5 h-5 text-emerald-300" />
                ) : (
                  <Play className="w-5 h-5 text-emerald-300 fill-emerald-300" />
                )}
              </button>
              <button
                onClick={() => {
                  setSecondsRemaining(totalSeconds);
                  setIsRunning(true);
                }}
                className="p-3.5 rounded-full bg-emerald-950/40 hover:bg-emerald-900/50 border border-emerald-800/40 text-emerald-400 transition-all active:scale-95"
                title="Reset Timer"
              >
                <RotateCcw className="w-4 h-4" />
              </button>
            </div>
          </>
        ) : (
          /* Finished State */
          <div className="glass-panel p-6 rounded-2xl border border-emerald-500/40 w-full animate-in fade-in zoom-in duration-300">
            <div className="w-12 h-12 rounded-full bg-emerald-900/60 border border-emerald-500/50 flex items-center justify-center mx-auto mb-4 text-emerald-300">
              <CheckCircle className="w-6 h-6" />
            </div>
            <h3 className="text-xl font-serif text-emerald-50">
              Welcome back to the digital realm.
            </h3>
            <p className="text-xs text-emerald-300/80 mt-1 font-sans">
              You completed your {initialMinutes}-minute disconnect at {sanctuaryName}.
            </p>

            {/* Quick reflection input */}
            <div className="mt-4 text-left">
              <label className="text-[11px] font-mono text-emerald-400/80 block mb-1">
                Optional: What sensory detail did you notice?
              </label>
              <input
                type="text"
                value={reflectionNotes}
                onChange={(e) => setReflectionNotes(e.target.value)}
                placeholder="e.g. Smell of damp pine, watched sparrows drink..."
                className="w-full bg-[#101b17] border border-emerald-800/50 rounded-lg p-2.5 text-xs text-emerald-100 placeholder:text-emerald-700 focus:outline-none focus:border-emerald-500"
              />
            </div>

            <button
              onClick={handleFinishAndSave}
              className="w-full mt-5 py-3 rounded-xl bg-gradient-to-r from-emerald-600 to-teal-600 hover:from-emerald-500 hover:to-teal-500 text-stone-950 font-semibold text-sm transition-all shadow-lg shadow-emerald-950 cursor-pointer"
            >
              Complete &amp; Return to Workspace
            </button>
          </div>
        )}
      </div>

      {/* Bottom Lock Reminder */}
      <div className="w-full max-w-md text-center relative z-10">
        <p className="text-[11px] font-mono text-emerald-500/60">
          Tip: You can lock your device screen now. The time will continue offline.
        </p>
      </div>
    </div>
  );
};

'use client';

import React, { useState, useEffect } from 'react';
import { Header } from '@/components/Header';
import { MoodSelector } from '@/components/MoodSelector';
import { SanctuaryCard } from '@/components/SanctuaryCard';
import { DisconnectModal } from '@/components/DisconnectModal';
import { SanctuaryRecord, INITIAL_SANCTUARIES } from '@/db/sanctuaries-data';
import { chime } from '@/lib/audio';
import {
  Compass,
  Sparkles,
  TreePine,
  ShieldCheck,
  Terminal,
  ExternalLink,
  Cpu,
  Database,
  GitCommit,
} from 'lucide-react';

export default function Home() {
  const [soundEnabled, setSoundEnabled] = useState<boolean>(true);
  const [dbConnected, setDbConnected] = useState<boolean>(false);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [selectedMinutes, setSelectedMinutes] = useState<number>(10);
  const [isDisconnectOpen, setIsDisconnectOpen] = useState<boolean>(false);

  // Current Sanctuary & Mission state
  const [currentSanctuary, setCurrentSanctuary] = useState<SanctuaryRecord>(INITIAL_SANCTUARIES[0]);
  const [alternatives, setAlternatives] = useState<SanctuaryRecord[]>(INITIAL_SANCTUARIES.slice(1, 3));
  const [sensoryMission, setSensoryMission] = useState({
    title: 'The Dense Tree Canopy Grounding Protocol',
    location: INITIAL_SANCTUARIES[0].name,
    targetDurationMins: 10,
    instructions: [
      `Walk unhurriedly to ${INITIAL_SANCTUARIES[0].name} without checking your email or notifications.`,
      'Sit on the stone perimeter with eyes closed for 3 minutes, listening to leaves rustle.',
      'Touch the cool moss on the stone well to register physical tactile grounding.',
      'Count 10 deep belly breaths before standing up.',
    ],
    lockoutMessage: 'Put your phone into your pocket or backpack now. Look up at the canopy. Step outside.',
  });
  const [dataSource, setDataSource] = useState<string>('Local Fast Vector Engine');

  // Check initial backend health & database connection
  useEffect(() => {
    async function checkHealth() {
      try {
        const res = await fetch('/api/agent');
        if (res.ok) {
          const json = await res.json();
          if (json.vectorDatabase?.includes('Tiger Data')) {
            setDbConnected(true);
          }
        }
      } catch (err) {
        // In local mode without server, defaults are active
      }
    }
    checkHealth();
  }, []);

  const handleToggleSound = () => {
    const next = !soundEnabled;
    setSoundEnabled(next);
    chime.enabled = next;
    if (next) {
      chime.playZenChime('tick');
    }
  };

  const handleSearch = async (params: {
    mood: string;
    minutes: number;
    needQuiet: boolean;
  }) => {
    setIsLoading(true);
    setSelectedMinutes(params.minutes);

    try {
      const res = await fetch('/api/agent', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          mood: params.mood,
          minutes: params.minutes,
          needQuiet: params.needQuiet,
        }),
      });

      if (res.ok) {
        const json = await res.json();
        if (json.success && json.data) {
          setCurrentSanctuary(json.data.sanctuary);
          setAlternatives(json.data.alternatives || []);
          setSensoryMission(json.data.sensoryMission);
          setDataSource(
            json.meta?.databaseConnected
              ? 'Tiger Data (PostgreSQL + pgvector)'
              : 'Local Vector Engine'
          );
          if (json.meta?.databaseConnected) {
            setDbConnected(true);
          }
        }
      }
    } catch (err) {
      console.warn('Discovery API call failed, falling back to local dataset:', err);
    } finally {
      setIsLoading(false);
      chime.playZenChime('tick');
    }
  };

  const handleSelectAlternative = (alt: SanctuaryRecord) => {
    setCurrentSanctuary(alt);
    setSensoryMission({
      title: `The ${alt.sensory_features[0]?.replace(/\b\w/g, (c) => c.toUpperCase()) || 'Nature'} Grounding Protocol`,
      location: alt.name,
      targetDurationMins: selectedMinutes,
      instructions: [
        `Walk unhurriedly to ${alt.name} without looking at navigation maps unless necessary.`,
        `Find a resting spot near the ${alt.sensory_features[0] || 'greenery'} and pause for 5 minutes.`,
        `Notice how the ambient light filters through the environment.`,
        `Resist taking photos—absorb the spot purely through memory.`,
      ],
      lockoutMessage: 'Put your phone into your pocket or backpack now. Look up at the canopy. Step outside.',
    });
    chime.playZenChime('tick');
  };

  return (
    <div className="min-h-screen flex flex-col bg-[#0d1312] text-emerald-100">
      {/* Top Header */}
      <Header
        soundEnabled={soundEnabled}
        onToggleSound={handleToggleSound}
        dbConnected={dbConnected}
      />

      {/* Main Content Area */}
      <main className="flex-1 max-w-4xl mx-auto w-full px-4 py-6 sm:py-10 space-y-8">
        {/* Hero Section */}
        <div className="text-center space-y-3">
          <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-emerald-950/90 border border-emerald-800/40 text-emerald-300 text-xs font-mono shadow-sm">
            <TreePine className="w-3.5 h-3.5 text-emerald-400" />
            Hacktoberfest 2026 AI Challenge &bull; Week 1: Touch Grass
          </div>
          <h1 className="text-3xl sm:text-5xl font-serif text-emerald-50 tracking-tight font-normal">
            Escape screen fatigue in 30 seconds.
          </h1>
          <p className="text-sm sm:text-base text-emerald-300/70 max-w-2xl mx-auto leading-relaxed">
            GroundTrace discovers secluded micro-sanctuaries within a 5-to-15 minute walk,
            gives you a restorative tactile sensory mission, and locks your screen so you can
            physically step outside.
          </p>
        </div>

        {/* Step 1: Input Form */}
        <section aria-label="Mood Selector">
          <MoodSelector onSearch={handleSearch} isLoading={isLoading} />
        </section>

        {/* Step 2: Instant Recommendation */}
        <section aria-label="Micro-Sanctuary Recommendation">
          <div className="flex items-center justify-between mb-3 px-1">
            <span className="text-[11px] font-mono text-emerald-400 uppercase tracking-widest font-medium">
              Step 2 • Instant Recommendation
            </span>
            <span className="text-[11px] font-mono text-emerald-500/70">
              Source: {dataSource}
            </span>
          </div>

          <SanctuaryCard
            sanctuary={currentSanctuary}
            alternatives={alternatives}
            sensoryMission={sensoryMission}
            onSelectAlternative={handleSelectAlternative}
            onStartDisconnect={() => setIsDisconnectOpen(true)}
            dataSource={dataSource}
          />
        </section>

        {/* Hacktoberfest Partner Tracks Architecture Showcase */}
        <section
          aria-label="Partner Tracks Architecture"
          className="glass-panel rounded-2xl p-6 border border-emerald-950/80 mt-12 space-y-4"
        >
          <div className="flex items-center gap-2 text-xs font-mono text-emerald-400 uppercase tracking-wider font-semibold">
            <Terminal className="w-4 h-4 text-emerald-300" />
            Hacktoberfest 2026 Category Stacking Architecture
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-4 pt-1">
            {/* Mastra Card */}
            <div className="p-4 rounded-xl bg-[#13211d]/70 border border-emerald-900/40 space-y-2">
              <div className="flex items-center gap-2 text-emerald-200 font-medium text-sm">
                <Cpu className="w-4 h-4 text-emerald-400" />
                1. Mastra Framework
              </div>
              <p className="text-xs text-emerald-300/70 leading-relaxed font-sans">
                TypeScript agent orchestration using <code className="text-emerald-300">@mastra/core</code>,
                tools for semantic spatial retrieval, and dynamic screen-free sensory mindfulness prompt synthesis.
              </p>
            </div>

            {/* Tiger Data Card */}
            <div className="p-4 rounded-xl bg-[#13211d]/70 border border-emerald-900/40 space-y-2">
              <div className="flex items-center gap-2 text-emerald-200 font-medium text-sm">
                <Database className="w-4 h-4 text-emerald-400" />
                2. Tiger Data (pgvector)
              </div>
              <p className="text-xs text-emerald-300/70 leading-relaxed font-sans">
                PostgreSQL cloud instance indexing micro-sanctuaries with 768-dimensional vector embeddings and
                sub-millisecond <code className="text-emerald-300">&lt;=&gt;</code> cosine distance queries.
              </p>
            </div>

            {/* Entire CLI Card */}
            <div className="p-4 rounded-xl bg-[#13211d]/70 border border-emerald-900/40 space-y-2">
              <div className="flex items-center gap-2 text-emerald-200 font-medium text-sm">
                <GitCommit className="w-4 h-4 text-emerald-400" />
                3. Entire CLI Checkpoints
              </div>
              <p className="text-xs text-emerald-300/70 leading-relaxed font-sans">
                Configured via <code className="text-emerald-300">entire.yaml</code> to capture development
                checkpoints and agent runtime transcripts for the DEV Community submission.
              </p>
            </div>
          </div>
        </section>
      </main>

      {/* Disconnect Lockout Modal */}
      <DisconnectModal
        isOpen={isDisconnectOpen}
        onClose={() => setIsDisconnectOpen(false)}
        sanctuaryName={currentSanctuary.name}
        sanctuaryId={currentSanctuary.id}
        initialMinutes={selectedMinutes}
        sensoryMissionTitle={sensoryMission.title}
        soundEnabled={soundEnabled}
        onToggleSound={handleToggleSound}
      />

      {/* Footer */}
      <footer className="w-full border-t border-emerald-950/60 py-6 text-center text-xs text-emerald-600/70 font-mono">
        <div className="max-w-4xl mx-auto px-4 flex flex-col sm:flex-row items-center justify-between gap-3">
          <div>
            GroundTrace &bull; Hacktoberfest 2026: Touch Grass Challenge
          </div>
          <div className="flex items-center gap-4 text-emerald-500/80">
            <span>Mastra</span>
            <span>&bull;</span>
            <span>Tiger Data</span>
            <span>&bull;</span>
            <span>Entire</span>
          </div>
        </div>
      </footer>
    </div>
  );
}

