import { SanctuaryRecord } from '../db/sanctuaries-data';
import { getEmbedding, generateDeterministicEmbedding } from './embeddings';

interface OsmElement {
  type: 'node' | 'way' | 'relation';
  id: number;
  lat?: number;
  lon?: number;
  center?: { lat: number; lon: number };
  tags?: Record<string, string>;
}

/**
 * Calculates Haversine distance in meters between two lat/lng points
 */
export function calculateDistanceMeters(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number
): number {
  const R = 6371e3; // Earth radius in meters
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return Math.round(R * c);
}

/**
 * Fetches real nearby parks, gardens, and nature spots using OpenStreetMap Overpass API
 */
export async function fetchLiveNearbySanctuaries(
  userLat: number,
  userLng: number,
  radiusMeters: number = 1800,
  maxResults: number = 8
): Promise<SanctuaryRecord[]> {
  const overpassQuery = `
    [out:json][timeout:6];
    (
      node["leisure"="park"](around:${radiusMeters},${userLat},${userLng});
      way["leisure"="park"](around:${radiusMeters},${userLat},${userLng});
      node["leisure"="garden"](around:${radiusMeters},${userLat},${userLng});
      way["leisure"="garden"](around:${radiusMeters},${userLat},${userLng});
      node["amenity"="bench"](around:${radiusMeters / 2},${userLat},${userLng});
      way["natural"="wood"](around:${radiusMeters},${userLat},${userLng});
      node["natural"="tree"](around:${radiusMeters / 2},${userLat},${userLng});
      way["landuse"="grass"](around:${radiusMeters},${userLat},${userLng});
    );
    out center ${maxResults * 2};
  `;

  const endpoints = [
    'https://overpass-api.de/api/interpreter',
    'https://lz4.overpass-api.de/api/interpreter',
    'https://overpass.kumi.systems/api/interpreter',
  ];

  let rawElements: OsmElement[] = [];

  for (const endpoint of endpoints) {
    try {
      const controller = new AbortController();
      const timeoutId = setTimeout(() => controller.abort(), 6500);

      const res = await fetch(endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
        body: `data=${encodeURIComponent(overpassQuery)}`,
        signal: controller.signal,
      });

      clearTimeout(timeoutId);

      if (res.ok) {
        const json = await res.json();
        if (Array.isArray(json.elements) && json.elements.length > 0) {
          rawElements = json.elements;
          break;
        }
      }
    } catch (err) {
      // Try next mirror if this one times out or errors
      continue;
    }
  }

  if (rawElements.length === 0) {
    return [];
  }

  // Filter and process spots
  const parsedSpots: SanctuaryRecord[] = [];
  const seenNames = new Set<string>();

  for (const el of rawElements) {
    const lat = el.lat ?? el.center?.lat;
    const lon = el.lon ?? el.center?.lon;
    if (lat === undefined || lon === undefined) continue;

    const tags = el.tags || {};
    const distanceMeters = calculateDistanceMeters(userLat, userLng, lat, lon);
    const walkMins = Math.max(3, Math.round(distanceMeters / 80));

    // Determine category
    let category: SanctuaryRecord['category'] = 'pocket_park';
    let defaultName = 'Neighborhood Green Space';

    if (tags.leisure === 'garden') {
      category = 'botanical_corner';
      defaultName = 'Community Botanical Garden';
    } else if (tags.amenity === 'bench') {
      category = 'quiet_bench';
      defaultName = 'Resting Tree Bench';
    } else if (tags.natural === 'wood' || tags.landuse === 'forest') {
      category = 'urban_grove';
      defaultName = 'Urban Tree Grove';
    } else if (tags.natural === 'tree') {
      category = 'quiet_bench';
      defaultName = 'Canopy Tree Shelter';
    }

    const name = tags.name || tags['name:en'] || defaultName;
    if (seenNames.has(name)) continue;
    seenNames.add(name);

    // Derive sensory features from tags
    const sensoryFeatures: string[] = [];
    if (tags.natural === 'water' || tags.water || tags.fountain) {
      sensoryFeatures.push('ambient water sound');
    }
    if (tags.trees || tags.wood || category === 'urban_grove') {
      sensoryFeatures.push('mature tree canopy');
    } else {
      sensoryFeatures.push('fresh greenery');
    }
    sensoryFeatures.push('open air breeze');
    sensoryFeatures.push(`${distanceMeters}m walk`);

    const neighborhood = tags['addr:suburb'] || tags['addr:district'] || tags['addr:city'] || 'Local Area';

    const ambiance = tags.description ||
      `A real physical green sanctuary located ${distanceMeters} meters away (${walkMins} min walk). Step outside into the natural surroundings to disconnect from screen glare.`;

    const fullDescription = `${name}. Category: ${category}. Located at ${neighborhood}. ${ambiance} Sensory elements: ${sensoryFeatures.join(', ')}`;

    // Quick deterministic embedding for fast spatial ranking
    const embedding = generateDeterministicEmbedding(fullDescription);

    parsedSpots.push({
      id: el.id,
      name,
      category,
      neighborhood: `${neighborhood} (${distanceMeters}m)`,
      estimated_walk_mins: walkMins,
      shade_rating: category === 'urban_grove' ? 5 : 4,
      quiet_rating: category === 'quiet_bench' ? 5 : 4,
      ambiance_description: ambiance,
      sensory_features: sensoryFeatures,
      embedding,
      latitude: lat,
      longitude: lon,
    });

    if (parsedSpots.length >= maxResults) break;
  }

  return parsedSpots;
}

