4: /**
5:  * Calculates Haversine distance in meters between two lat/lng points
6:  */
7: export function calculateDistanceMeters(
8:   lat1: number,
9:   lon1: number,
10:   lat2: number,
11:   lon2: number
12: ): number {
13:   const R = 6371e3; // Earth radius in meters
14:   const dLat = ((lat2 - lat1) * Math.PI) / 180;
15:   const dLon = ((lon2 - lon1) * Math.PI) / 180;
16:   const a =
17:     Math.sin(dLat / 2) * Math.sin(dLat / 2) +
18:     Math.cos((lat1 * Math.PI) / 180) *
19:       Math.cos((lat2 * Math.PI) / 180) *
20:       Math.sin(dLon / 2) *
21:       Math.sin(dLon / 2);
22:   const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
23:   return Math.round(R * c);
24: }
