50:  * Searches micro-sanctuaries using Tiger Data pgvector cosine distance `<=>`.
51:  * If database is not configured, performs in-memory cosine vector ranking.
52:  */
53: export async function querySanctuariesVector(
54:   embedding: number[],
55:   maxWalkMins: number = 20,
56:   limit: number = 3
57: ): Promise<SanctuaryRecord[]> {
58:   const p = getPool();
59: 
60:   if (p) {
61:     try {
62:       const vectorLiteral = formatPgVector(embedding);
63:       const query = `
64:         SELECT 
65:           id, 
66:           name, 
67:           category, 
68:           neighborhood, 
69:           estimated_walk_mins, 
70:           shade_rating, 
71:           quiet_rating, 
72:           ambiance_description, 
73:           sensory_features, 
74:           (embedding <=> $1::vector) AS distance
75:         FROM micro_sanctuaries
76:         WHERE estimated_walk_mins <= $2
77:         ORDER BY distance ASC
78:         LIMIT $3;
79:       `;
80: 
81:       const result: QueryResult = await p.query(query, [vectorLiteral, maxWalkMins, limit]);
82:       if (result.rows.length > 0) {
83:         return result.rows.map((row) => ({
84:           id: row.id,
85:           name: row.name,
86:           category: row.category,
87:           neighborhood: row.neighborhood,
88:           estimated_walk_mins: row.estimated_walk_mins,
89:           shade_rating: row.shade_rating,
90:           quiet_rating: row.quiet_rating,
91:           ambiance_description: row.ambiance_description,
92:           sensory_features: row.sensory_features,
93:           distance: parseFloat(row.distance),
94:         }));
95:       }
96:     } catch (dbError) {
97:       console.warn('Tiger Data pgvector query failed, using in-memory vector fallback:', dbError);
98:     }
99:   }
100: 
101:   // Graceful In-Memory Semantic Cosine Ranking Fallback
102:   const candidateList = INITIAL_SANCTUARIES.filter(
103:     (s) => s.estimated_walk_mins <= maxWalkMins
104:   );
105: 
106:   const scored = candidateList.map((sanctuary) => {
107:     const sim = sanctuary.embedding ? cosineSimilarity(embedding, sanctuary.embedding) : 0.5;
108:     const distance = 1 - sim; // Cosine distance = 1 - cosine similarity
109:     return {
110:       ...sanctuary,
111:       distance: Number(distance.toFixed(4)),
112:     };
113:   });
114: 
115:   scored.sort((a, b) => (a.distance ?? 1) - (b.distance ?? 1));
116:   return scored.slice(0, limit);
117: }
