import dotenv from 'dotenv';
dotenv.config({ path: '.env.local' });
import { runGroundTraceDiscovery } from './src/mastra/agents/sanctuaryAgent';

async function test() {
  console.log('--- TEST 1: Demo / Tiger Data (No GPS coordinates) ---');
  const res1 = await runGroundTraceDiscovery({
    mood: 'Severe screen glare and eye strain',
    maxWalkMins: 15,
  });
  console.log('Test 1 Data Source:', res1.dataSource);
  console.log('Test 1 Sanctuary:', res1.sanctuary.name);
  console.log('Test 1 Walk Minutes:', res1.sanctuary.estimated_walk_mins);
  console.log('Test 1 Alternatives Count:', res1.alternatives.length);

  console.log('\n--- TEST 2: Live GPS (London area: lat 51.5074, lng -0.1278) ---');
  const res2 = await runGroundTraceDiscovery({
    mood: 'need quiet shade and trees',
    maxWalkMins: 25,
    coordinates: { lat: 51.5074, lng: -0.1278 },
  });
  console.log('Test 2 Data Source:', res2.dataSource);
  console.log('Test 2 Sanctuary:', res2.sanctuary.name);
  console.log('Test 2 Walk Minutes:', res2.sanctuary.estimated_walk_mins);
  console.log('Test 2 GPS Coords:', res2.sanctuary.latitude, res2.sanctuary.longitude);
